// Somebody else's words, on the page. The SAME quote drawn by `renderQuoteSvg` for a
// social preview: the accent, the size ladder and the trim all come out of
// `quote-card`, so the card and the link preview cannot drift apart. Two emitters, one
// set of rules — the terminal and its still are the same arrangement.
//
// It renders a real `<blockquote>` with a real `<cite>`, because that is what this is,
// and a screen reader announcing "blockquote" is information the styling cannot carry.

import {
  type Quote as QuoteData,
  quoteAccent,
  quoteFontSize,
  quoteTrim,
} from "@/registry/base-nova/lib/quote-card"
import "./quote.css"

export interface QuoteProps extends QuoteData {
  /** Display sets the words at the size the preview would, which is the point of the
   *  ladder: a short quote is a poster and a long one is a paragraph. Inline keeps the
   *  page's own type, for a quote inside prose that must not shout over it. */
  display?: boolean
  /** Cap the words the way a preview does. Off by default: a page has room, and
   *  truncating on it would lose the end of what somebody said. */
  trim?: boolean
  /** The measured width the ladder steps against. Only for `display`, and only worth
   *  passing when the card is not the usual reading column. */
  width?: number
  className?: string
  children?: React.ReactNode
}

/** The reading column a display quote is set for, matching the site's `max-w-3xl`. */
export const QUOTE_WIDTH = 768

export function Quote({
  text,
  author,
  source,
  date,
  seed,
  display = false,
  trim = false,
  width = QUOTE_WIDTH,
  className,
  children,
}: QuoteProps) {
  const words = trim ? quoteTrim(text) : text
  const accent = quoteAccent(seed ?? author?.name ?? text)
  // The one place the still's arithmetic reaches the DOM: the size a preview would
  // set these words at, in the units CSS wants.
  const size = display ? `${quoteFontSize(words.length, width)}px` : undefined
  return (
    <figure
      className={`ag-quote${className ? ` ${className}` : ""}`}
      data-display={display ? "" : undefined}
      style={{ "--ag-quote-accent": accent } as React.CSSProperties}
    >
      <blockquote className="ag-quote-body" style={{ fontSize: size }}>
        {children ?? <p>{words}</p>}
      </blockquote>
      {(author || date || source) && (
        <figcaption className="ag-quote-by">
          {author?.avatar && (
            // Decorative: the name beside it is the accessible attribution, and a
            // screen reader reading the name twice is noise.
            // biome-ignore lint/performance/noImgElement: an item cannot assume next/image
            <img
              className="ag-quote-face"
              src={author.avatar}
              alt=""
              width={40}
              height={40}
            />
          )}
          {author &&
            (author.href ? (
              <cite>
                <a href={author.href}>{author.name}</a>
              </cite>
            ) : (
              <cite>{author.name}</cite>
            ))}
          {date && <span className="ag-quote-date">{date}</span>}
          {source && (
            <a
              className="ag-quote-source"
              href={source}
              target="_blank"
              rel="noopener noreferrer"
            >
              source ↗
            </a>
          )}
        </figcaption>
      )}
    </figure>
  )
}

/* The accent is set inline from the seed, so a quote keeps its colour without a
   palette to maintain and a wall of them is varied by construction. */
.ag-quote {
  margin: 0;
  padding-inline-start: 1rem;
  border-inline-start: 2px solid
    color-mix(in oklch, var(--ag-quote-accent) 55%, transparent);
}
.ag-quote[data-display] {
  padding-inline-start: 1.5rem;
}
.ag-quote-body {
  margin: 0;
  font-style: italic;
  color: color-mix(in oklch, var(--foreground) 90%, transparent);
}
.ag-quote-body > p {
  margin: 0;
}
.ag-quote-body > p + p {
  margin-block-start: 0.5rem;
}
/* Display sets its own size from the ladder, so the leading has to be a ratio: a
   fixed line-height would space a poster and a paragraph identically. */
.ag-quote[data-display] .ag-quote-body {
  line-height: 1.35;
  text-wrap: balance;
}

.ag-quote-by {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-block-start: 0.75rem;
  font-size: var(--text-xs, 0.75rem);
  font-style: normal;
  color: var(--muted-foreground);
}
.ag-quote[data-display] .ag-quote-by {
  gap: 0.75rem;
  margin-block-start: 1.5rem;
  font-size: var(--text-sm, 0.875rem);
}
.ag-quote-face {
  flex: none;
  width: 1.5rem;
  height: 1.5rem;
  object-fit: cover;
  border-radius: 9999px;
}
.ag-quote[data-display] .ag-quote-face {
  width: 2.5rem;
  height: 2.5rem;
}
.ag-quote-by cite {
  font-style: normal;
  color: var(--ag-quote-accent);
}
.ag-quote-by a {
  color: inherit;
  text-decoration: none;
}
.ag-quote-by a:hover {
  text-decoration: underline;
}
/* The date and the source are metadata, so they take the metadata voice. */
.ag-quote-date,
.ag-quote-source {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: var(--text-xs, 0.75rem);
  color: color-mix(in oklch, var(--muted-foreground) 80%, transparent);
}
.ag-quote-source {
  margin-inline-start: auto;
}
